const empresa = $('📊 Obtener Perfil Empresa').item.json.records[0]?.fields || {};
const serviciosData = $('📦 Obtener Servicios Activos').item.json.records || [];
const temasExistentes = $('📋 Obtener Temas Existentes').item.json.records || [];

const servicios = serviciosData
  .map(p => `- ${p.fields['Nombre de Servicio']}: ${p.fields['Descripción comercial'] || ''}`.slice(0, 200))
  .join('\n');

const temasYaCreados = temasExistentes
  .map(t => t.fields['Tema'])
  .filter(Boolean)
  .join(', ');

const pendientes = temasExistentes.length;

const maxSemana = temasExistentes.length > 0
  ? Math.max(...temasExistentes.map(t => t.fields['Semana_Numero'] || 0))
  : 0;

const instrucciones_ia = empresa['Instrucciones_IA'] || '';

return [{
  json: {
    empresa_nombre: empresa['\uFEFFnombre_empresa'] || 'Crating Express',
    empresa_descripcion: empresa['descripción_corta'] || '',
    empresa_propuesta_valor: empresa['propuesta_valor'] || '',
    empresa_ciudad: empresa['ciudad base'] || 'Miami, FL',
    empresa_web: empresa['sitio_web'] || 'cratingexpress.com',
    servicios_resumen: servicios,
    temas_pendientes: pendientes,
    temas_ya_creados: temasYaCreados,
    proxima_semana: maxSemana + 1,
    temas_a_generar: Math.max(0, 6 - pendientes),
    instrucciones_ia: instrucciones_ia
  }
}];

// Soporta Gemini, Groq y OpenAI
const raw = $input.item.json;
const aiResponse = raw.candidates?.[0]?.content?.parts?.[0]?.text
  || raw.choices?.[0]?.message?.content
  || raw.message?.content
  || raw.text
  || raw.content
  || (typeof raw === 'string' ? raw : JSON.stringify(raw))
  || '{}';

let data;
try {
  const parsed = typeof aiResponse === 'object' ? aiResponse : JSON.parse(aiResponse);
  data = parsed;
} catch(e) {
  const match = String(aiResponse).match(/\{[\s\S]*\}/);
  try { data = match ? JSON.parse(match[0]) : { temas: [] }; }
  catch(e2) { data = { temas: [] }; }
}

const contexto = $('🔧 Preparar Contexto').item.json;
const temas = data.temas || [];

if (temas.length === 0) {
  return [{ json: { error: true, raw: String(aiResponse).slice(0, 500) } }];
}

return temas.map((tema, i) => ({
  json: {
    tema: tema.tema,
    descripcion: tema.descripcion,
    keyword_principal: tema.keyword_principal || '',
    pain_point: tema.pain_point || '',
    punto_fuerte: tema.punto_fuerte || '',
    llamada_accion: tema.llamada_accion || '',
    palabras_clave: tema.palabras_clave,
    tipo: tema.tipo,
    servicio_vinculado: tema.servicio_vinculado || '',
    semana_numero: contexto.proxima_semana + i,
    empresa: contexto.empresa_nombre,
    error: false
  }
}));

