const gscData = $input.first().json;
const ctx = $('🔧 Preparar Contexto').item.json;

// Extraer queries reales de GSC
let keywordsGSC = '';
let keywordsList = [];

try {
  const rows = gscData.rows || [];
  if (rows.length > 0) {
    keywordsList = rows
      .filter(r => r.clicks > 0 || r.impressions > 0)
      .slice(0, 20)
      .map(r => ({
        query: r.keys[0],
        clicks: r.clicks,
        impressions: r.impressions,
        position: Math.round(r.position * 10) / 10
      }));

    keywordsGSC = keywordsList
      .map(k => `- "${k.query}" (clicks: ${k.clicks}, posición: ${k.position})`)
      .join('\n');
  }
} catch(e) {
  keywordsGSC = 'No disponible';
}

// Si no hay datos de GSC, usar señal de aviso
const hasGSCData = keywordsList.length > 0;

return [{
  json: {
    ...ctx,
    keywordsGSC,
    keywordsList,
    hasGSCData,
    gscError: gscData.error?.message || null
  }
}];

